Este código de un formulario de búsqueda tiene 4 bugs. Encuéntralos y explica cómo arreglarlos:

```
async function search(query) {
  const results = await fetch("/api/search?q=" + query);
  // Bug 1: no parsea JSON
  displayResults(results);
}

let debounceTimer;
function onInput(e) {
  clearTimeout(debounceTimer);
  debounceTimer = setTimeout(search(e.target.value), 300);
  // Bug 2: ejecuta search inmediatamente en vez de pasar referencia
}

function displayResults(data) {
  const container = document.getElementById("results");
  data.forEach(item => {
    container.innerHTML += `<div>${item.name}</div>`;
    // Bug 3: += en innerHTML destruye event listeners existentes
  });
}

document.querySelector(".search").addEventListener("click", onInput);
// Bug 4: evento incorrecto — debería ser input, no click
```

Este código funciona pero es muy lento con datos grandes. Identifica los problemas de rendimiento y reescribe las funciones optimizadas:

```python
# Función 1: Buscar duplicados (O(n²) actual)
def find_duplicates(items):
    duplicates = []
    for i in range(len(items)):
        for j in range(i+1, len(items)):
            if items[i] == items[j] and items[i] not in duplicates:
                duplicates.append(items[i])
    return duplicates

# Función 2: Contar palabras en archivo (lee todo en memoria)
def count_words(filename):
    content = open(filename).read()
    words = content.split()
    word_count = {}
    for word in words:
        if word in word_count:
            word_count[word] = word_count[word] + 1
        else:
            word_count[word] = 1
    return word_count
```
